\set ON_ERROR_STOP on
BEGIN;
UPDATE public.pos_rpc_rate_limits SET blocked_until=now()+interval '5 minutes' WHERE license_key='lab-license-a' AND device_fingerprint='lab-device-a' AND rpc_name='pos_create_cloud_sale_cashier' AND scope='POS_WRITE' AND staff_session_hash=encode(extensions.digest('lab-admin-session','sha256'),'hex');
DO $test$ DECLARE h text; n bigint; BEGIN
SELECT count(*) INTO n FROM public.pos_rpc_rate_limits WHERE license_key='lab-license-a' AND device_fingerprint='lab-device-a' AND rpc_name='pos_create_cloud_sale_cashier' AND blocked_until>now();
IF n=0 THEN RAISE EXCEPTION 'RATE_LIMIT_SETUP_MISSING'; END IF;
h:=private.financial_operation_hash('sale.cashier_inventory',private.canonical_financial_request_v1('sale.cashier_inventory','{"cash_session_id":"lab-cash-a","sale":{"id":"lab-race-29","subtotal":20,"total":20,"payment_method":"cash","amount_paid":20,"balance_due":0,"change_amount":0},"items":[{"id":"lab-race-29-line","product_id":"lab-race-29-product","product_name":"Synthetic race 29","quantity":2,"unit_price":10,"line_subtotal":20,"line_total":20}],"payments":[{"id":"lab-race-29-payment","method":"cash","amount":20,"received_amount":20,"change_amount":0}],"restaurant_settlement":{"parent_order_id":"lab-race-29","parent_order_version":"2026-10-01T00:00:00Z"}}'::jsonb),'admin:00000000-0000-0000-0000-0000000000aa','lab-cash-a','lab-station-a');
BEGIN PERFORM public.pos_execute_financial_operation_v1('lab-license-a','lab-device-a','lab-device-token-a','lab-admin-session','lab-rate-block-key',h,'sale.cashier_inventory','{"cash_session_id":"lab-cash-a","sale":{"id":"lab-race-29","subtotal":20,"total":20,"payment_method":"cash","amount_paid":20,"balance_due":0,"change_amount":0},"items":[{"id":"lab-race-29-line","product_id":"lab-race-29-product","product_name":"Synthetic race 29","quantity":2,"unit_price":10,"line_subtotal":20,"line_total":20}],"payments":[{"id":"lab-race-29-payment","method":"cash","amount":20,"received_amount":20,"change_amount":0}],"restaurant_settlement":{"parent_order_id":"lab-race-29","parent_order_version":"2026-10-01T00:00:00Z"}}'::jsonb); RAISE EXCEPTION 'RATE_LIMIT_NOT_ENFORCED'; EXCEPTION WHEN SQLSTATE 'P0001' THEN IF SQLERRM <> 'RESTAURANT_SETTLEMENT_SALE_NOT_CONFIRMED:RPC_RATE_LIMITED' THEN RAISE; END IF; END;
IF (SELECT stock FROM public.pos_products WHERE id='lab-race-29-product')<>20 OR (SELECT count(*) FROM public.pos_sales WHERE id LIKE 'lab-race-29%')<>0 OR (SELECT count(*) FROM public.pos_inventory_movements WHERE product_id='lab-race-29-product')<>0 OR (SELECT count(*) FROM public.pos_financial_operations WHERE idempotency_key='lab-rate-block-key')<>0 THEN RAISE EXCEPTION 'RATE_LIMIT_CHANGED_EFFECTS'; END IF;
END $test$;
ROLLBACK;
SELECT 'PASS_CASHIER_RATE_LIMIT_BLOCKS_INVENTORY_SALE' result;